  .container { max-width: 1100px; margin: 0 auto; padding: 0 24px; }

  /* Header */
  header {
    background: linear-gradient(135deg, #1A1A24 0%, #0F0F14 50%, #1A1A24 100%);
    border-bottom: 3px solid var(--gold);
    padding: 60px 0 40px;
    text-align: center;
