  }
  .chart-title {
    font-size: 1rem;
    color: var(--gold-light);
    margin-bottom: 16px;
    font-weight: 600;
  }

  /* Composer ranking table */
  .ranking-table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
  }
  .ranking-table th {
    text-align: left;
    padding: 12px 16px;
    background: var(--bg-section);
    color: var(--gold);
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    border-bottom: 2px solid var(--gold-dark);
