  .ranking-table td {
    padding: 12px 16px;
    border-bottom: 1px solid var(--border);
    font-size: 0.95rem;
  }
  .ranking-table tr:hover { background: rgba(212, 168, 67, 0.05); }
  .rank-num {
    color: var(--gold);
    font-weight: 700;
    font-size: 1.1rem;
    width: 40px;
